sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // --- 1. Get any value you need from the catalog item ---
    var catItem = new GlideRecord('sc_cat_item');
    if (!catItem.get(current.cat_item))
        return; // safety check

    var catItemName = catItem.getDisplayValue('name');

    // Example: pull a custom field from the catalog item to use as Requested For
    // Replace 'u_default_requested_for' with your actual field name on sc_cat_item
    var requestedFor = catItem.getValue('requested_for') ||
        current.getValue('requested_for'); // fallback to RITM value
    var userName = '';
    if (requestedFor) {
        var u = new GlideRecord('sys_user');
        if (u.get(requestedFor)) {
            userName = u.getDisplayValue('name');
        }
    }

    // --- 2. Update the parent request with the value from the catalog item ---
    var req = new GlideRecord('sc_request');
    if (req.get(current.request) && requestedFor) {
        req.setValue('requested_for', requestedFor);
        req.update();
    }

    // --- 3. Check for duplicate RITMs for this user & catalog item within 180 days ---
    var dup = new GlideRecord('sc_req_item');
    dup.addQuery('requested_for', requestedFor);
    dup.addQuery('cat_item', current.cat_item);
    dup.addQuery('sys_created_on', '>=', gs.daysAgoStart(180));
    dup.addQuery('sys_id', '!=', current.sys_id);
    dup.addQuery('state', '!=', '7'); // 7 = Closed/Cancelled
    dup.query();

    if (dup.next()) {

        // Build rejection message
        var lastRequestDate = new GlideDateTime(dup.sys_created_on);
        var rejectionMsg = userName + " cannot request the item '" + catItemName +
            "' again within 6 months. Last request was on " +
            lastRequestDate.getDisplayValue() +
            ". This item is restricted to one request within a six-month period.";

        gs.addErrorMessage(rejectionMsg);

        // --- 4. Reject the parent request ---
        if (req.get(current.request)) {
            req.setValue('approval', 'rejected');
            req.setValue('request_state', 'rejected');
            req.setValue('close_notes', rejectionMsg);
            req.update();
        }

        // --- 5. Update all RITMs for this request ---
        var ritm = new GlideRecord('sc_req_item');
        ritm.addQuery('request', current.request);
        ritm.query();
        while (ritm.next()) {
            ritm.setValue('state', 'closed_complete'); // or 'cancelled', etc.
            ritm.setValue('comments', rejectionMsg); // Additional comments (Customer visible)
            ritm.update();
        }

        current.setAbortAction(true); // Abort the current transaction
    }

})(current, previous);
